// Assembles the extension into dist/, ready to load unpacked or zip.
//
//   node build.js
//
// Node 18+, no dependencies, no install step.
//
// It is a build rather than a folder you can load directly for one reason:
// the masthead used on share cards ships as a data URL generated from
// assets/lockup.png, and the manifest expects the generated file to exist.
// Files are also listed explicitly rather than globbed, so a stray file left
// in the tree cannot silently end up in a release.

import { mkdirSync, rmSync, readFileSync, writeFileSync, copyFileSync, existsSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, resolve, join } from 'node:path'

const SRC = dirname(fileURLToPath(import.meta.url))
const TARGET = resolve(SRC, 'dist')

const FILES = [
  'manifest.json',
  'background/service-worker.js',
  'content/render.js',
  'content/twitter.js',
  'content/terminals.js',
  'content/axiom-bridge.js',
  'card.js',
  'share.js',
  'popup/popup.html',
  'popup/popup.css',
  'popup/popup.js',
  'privacy.html',
  'favicon-32.png',
  'assets/icons/icon16.png',
  'assets/icons/icon32.png',
  'assets/icons/icon48.png',
  'assets/icons/icon128.png'
]

rmSync(TARGET, { recursive: true, force: true })
mkdirSync(TARGET, { recursive: true })

for (const rel of FILES) {
  const from = join(SRC, rel)
  if (!existsSync(from)) throw new Error(`missing source file: ${from}`)
  const to = join(TARGET, rel)
  mkdirSync(dirname(to), { recursive: true })
  copyFileSync(from, to)
}

// The masthead ships as a data URL rather than a file. A chrome-extension://
// image needs a web_accessible_resources entry for every host the extension
// runs on — miss one and it silently fails to load, which is exactly what
// happened on the terminals — and even where it loads it taints the canvas, so
// toBlob() throws. A data URL is same-origin everywhere and taints nothing.
const png = readFileSync(join(SRC, 'assets/lockup.png')).toString('base64')
writeFileSync(
  join(TARGET, 'lockup-data.js'),
  '// Generated by build.js from assets/lockup.png. Do not edit.\n' +
  "const FC_LOCKUP = 'data:image/png;base64," + png + "'\n"
)

const manifest = JSON.parse(readFileSync(join(SRC, 'manifest.json'), 'utf8'))
console.log(`\n  ${manifest.name} v${manifest.version}  ${FILES.length + 1} files`)
console.log(`  built to ${TARGET}`)
console.log('\n  Load unpacked: chrome://extensions -> Developer mode -> Load unpacked -> dist/\n')
